CREATE OR REPLACE FUNCTION public.app_add_application_message_from_admin_to_university(p_application_id uuid, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_exists BOOLEAN;
    v_message_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF p_content IS NULL OR LENGTH(TRIM(p_content)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'empty_content');
    END IF;

    SELECT EXISTS(SELECT 1 FROM app.applications a WHERE a.id = p_application_id)
    INTO v_exists;

    IF NOT v_exists THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'application_not_found');
    END IF;

    INSERT INTO app.application_messages (application_id, sender_role, audience, content)
    VALUES (p_application_id, 'admin', 'university', p_content)
    RETURNING id INTO v_message_id;

    UPDATE app.applications
    SET
        last_message_at = NOW(),
        updated_at = NOW()
    WHERE id = p_application_id;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'message_id', v_message_id
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_add_application_message_from_university(p_application_id uuid, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_university_id UUID;
    v_exists BOOLEAN;
    v_message_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT
        raw_user_meta_data->>'role',
        (raw_user_meta_data->>'university_id')::UUID
    INTO v_role, v_university_id
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'university' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_university');
    END IF;

    IF v_university_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'university_not_configured');
    END IF;

    IF p_content IS NULL OR LENGTH(TRIM(p_content)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'empty_content');
    END IF;

    SELECT EXISTS(
        SELECT 1
        FROM app.applications a
        JOIN app.programs p ON p.id = a.program_id
        WHERE a.id = p_application_id
          AND p.university_id = v_university_id
    ) INTO v_exists;

    IF NOT v_exists THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'application_not_found');
    END IF;

    INSERT INTO app.application_messages (application_id, sender_role, audience, content)
    VALUES (p_application_id, 'university', 'admin_only', p_content)
    RETURNING id INTO v_message_id;

    UPDATE app.applications
    SET
        last_message_at = NOW(),
        updated_at = NOW()
    WHERE id = p_application_id;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'message_id', v_message_id
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_add_bobodo_feedback(p_session_id uuid, p_message_id uuid, p_rating text, p_comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_student_id UUID;
    v_feedback_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    IF p_rating NOT IN ('up','down') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_rating');
    END IF;

    SELECT student_id INTO v_student_id
    FROM app.bobodo_sessions
    WHERE id = p_session_id;

    IF v_student_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'session_not_found');
    END IF;

    IF v_student_id <> v_user_id THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_owner');
    END IF;

    INSERT INTO app.bobodo_feedback (session_id, message_id, student_id, rating, comment)
    VALUES (
        p_session_id,
        p_message_id,
        v_student_id,
        p_rating,
        NULLIF(TRIM(p_comment), '')
    )
    RETURNING id INTO v_feedback_id;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'feedback_id', v_feedback_id
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_ban_user_from_challenges(p_user_id uuid, p_reason text, p_banned_until timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_ban_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF p_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_user');
    END IF;

    IF p_reason IS NULL OR LENGTH(TRIM(p_reason)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_reason');
    END IF;

    INSERT INTO app.challenge_user_bans (user_id, reason, banned_until, created_by_admin_id)
    VALUES (p_user_id, TRIM(p_reason), p_banned_until, v_user_id)
    ON CONFLICT (user_id) DO UPDATE
    SET
        reason = EXCLUDED.reason,
        banned_until = EXCLUDED.banned_until,
        created_by_admin_id = EXCLUDED.created_by_admin_id,
        created_at = NOW()
    RETURNING id INTO v_ban_id;

    UPDATE app.challenge_participations
    SET is_active = FALSE
    WHERE user_id = p_user_id
      AND is_active = TRUE;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'ban_id', v_ban_id);
END;
$function$

