CREATE OR REPLACE FUNCTION public.app_admin_review_challenge_participation(p_participation_id uuid, p_status text, p_score integer, p_rank integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_status TEXT := LOWER(TRIM(COALESCE(p_status, '')));
    v_challenge_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF v_status NOT IN ('completed', 'rejected', 'won') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_status');
    END IF;

    SELECT challenge_id
    INTO v_challenge_id
    FROM app.challenge_participations
    WHERE id = p_participation_id
      AND is_active = TRUE;

    IF v_challenge_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'participation_not_found');
    END IF;

    UPDATE app.challenge_participations cp
    SET
        status = v_status,
        score = COALESCE(p_score, cp.score),
        rank = COALESCE(p_rank, cp.rank),
        completed_at = CASE
            WHEN v_status IN ('completed', 'won') THEN COALESCE(cp.completed_at, NOW())
            ELSE cp.completed_at
        END,
        reviewed_at = NOW(),
        reviewed_by_user_id = v_user_id
    WHERE cp.id = p_participation_id
      AND cp.is_active = TRUE;

    IF NOT FOUND THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'update_failed');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'participation_id', p_participation_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_review_challenge_video(p_participation_id uuid, p_moderation_status text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_status TEXT := LOWER(TRIM(COALESCE(p_moderation_status, '')));
    v_participation_id UUID;
    v_flags JSONB;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT raw_user_meta_data->>'role'
    INTO v_role
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'admin' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_admin');
    END IF;

    IF v_status NOT IN ('approved', 'rejected', 'blocked_ai') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_status');
    END IF;

    SELECT moderation_flags
    INTO v_flags
    FROM app.challenge_participations
    WHERE id = p_participation_id
      AND is_active = TRUE;

    IF v_flags IS NULL THEN
        v_flags := '{}'::JSONB;
    END IF;

    IF p_reason IS NOT NULL AND LENGTH(TRIM(p_reason)) > 0 THEN
        v_flags := v_flags || JSONB_BUILD_OBJECT('last_reason', TRIM(p_reason));
    END IF;

    UPDATE app.challenge_participations cp
    SET
        moderation_status = v_status,
        moderation_flags = v_flags,
        moderated_by_admin_id = v_user_id,
        moderated_at = NOW(),
        is_active = CASE
            WHEN v_status IN ('rejected', 'blocked_ai') THEN FALSE
            ELSE is_active
        END
    WHERE cp.id = p_participation_id
    RETURNING id INTO v_participation_id;

    IF v_participation_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'participation_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'participation_id', v_participation_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_start_hero_render(p_playlist_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
