        'config', v_config,
        'announcements', v_announcements,
        'partners', v_partners,
        'why_cards', v_why_cards,
        'videos', v_videos
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_add_challenge_comment(p_participation_id uuid, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_banned BOOLEAN;
    v_participation_exists BOOLEAN;
    v_comment_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    IF p_content IS NULL OR LENGTH(TRIM(p_content)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_content');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.challenge_user_bans b
        WHERE b.user_id = v_user_id
          AND (b.banned_until IS NULL OR b.banned_until > NOW())
    ) INTO v_is_banned;

    IF v_is_banned THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'banned_from_challenges');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.challenge_participations cp
        WHERE cp.id = p_participation_id
          AND cp.is_active = TRUE
          AND COALESCE(cp.video_url, cp.submission_url) IS NOT NULL
    ) INTO v_participation_exists;

    IF NOT v_participation_exists THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'participation_not_found');
    END IF;

    INSERT INTO app.challenge_comments (participation_id, user_id, content)
    VALUES (p_participation_id, v_user_id, TRIM(p_content))
    RETURNING id INTO v_comment_id;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'comment_id', v_comment_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_add_challenge_video(p_participation_id uuid, p_video_url text, p_thumbnail_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_banned BOOLEAN;
    v_owner_id UUID;
    v_url_trim TEXT;
    v_video_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.challenge_user_bans b
        WHERE b.user_id = v_user_id
          AND (b.banned_until IS NULL OR b.banned_until > NOW())
    ) INTO v_is_banned;

    IF v_is_banned THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'banned_from_challenges');
    END IF;

    SELECT user_id
    INTO v_owner_id
    FROM app.challenge_participations
    WHERE id = p_participation_id
      AND is_active = TRUE;

    IF v_owner_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'participation_not_found');
    END IF;

    IF v_owner_id <> v_user_id THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_owner');
    END IF;

    v_url_trim := NULLIF(TRIM(COALESCE(p_video_url, '')), '');
    IF v_url_trim IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_video_url');
    END IF;

