CREATE OR REPLACE FUNCTION public.app_student_start_duo_video(p_video_type text, p_video_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_is_banned BOOLEAN;
    v_type TEXT := LOWER(TRIM(COALESCE(p_video_type, '')));
    v_exists BOOLEAN;
    v_is_duo_source BOOLEAN := FALSE;
    v_new_free_video_id UUID;
    v_parent_type TEXT;
    v_parent_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    IF v_type NOT IN ('challenge', 'free') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_video_type');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.challenge_user_bans b
        WHERE b.user_id = v_user_id
          AND (b.banned_until IS NULL OR b.banned_until > NOW())
    ) INTO v_is_banned;

    IF v_is_banned THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'banned_from_challenges');
    END IF;

    IF v_type = 'challenge' THEN
        SELECT EXISTS (
            SELECT 1
            FROM app.challenge_participations cp
            WHERE cp.id = p_video_id
              AND cp.is_active = TRUE
              AND COALESCE(cp.video_url, cp.submission_url) IS NOT NULL
        ) INTO v_exists;

        IF NOT v_exists THEN
            RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'video_not_found');
        END IF;

        -- Interdire les duos à partir d'un duo de challenge
        SELECT COALESCE(cp.remix_type, 'none') = 'duo'
        INTO v_is_duo_source
        FROM app.challenge_participations cp
        WHERE cp.id = p_video_id;
    ELSE
        SELECT EXISTS (
            SELECT 1
            FROM app.free_videos fv
            WHERE fv.id = p_video_id
              AND fv.is_active = TRUE
              AND COALESCE(fv.video_url, '') <> ''
        ) INTO v_exists;

        IF NOT v_exists THEN
            RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'video_not_found');
        END IF;

        SELECT COALESCE(fv.remix_type, 'none') = 'duo'
        INTO v_is_duo_source
        FROM app.free_videos fv
        WHERE fv.id = p_video_id;
    END IF;

    IF v_is_duo_source THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'cannot_duo_from_duo');
    END IF;

    v_parent_type := v_type;
    v_parent_id := p_video_id;

    INSERT INTO app.free_videos (
        user_id,
        video_url,
        video_renditions,
        thumbnail_url,
        title,
        description,
        is_active,
        moderation_status,
        moderation_flags,
        parent_video_type,
        parent_video_id,
        remix_type
    )
    VALUES (
        v_user_id,
        '',
        NULL,
        NULL,
        NULL,
        NULL,
        TRUE,
        'pending',
        NULL,
        v_parent_type,
        v_parent_id,
        'duo'
    )
    RETURNING id INTO v_new_free_video_id;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'video_type', 'free',
        'video_id', v_new_free_video_id,
        'remix_type', 'duo',
        'parent_video_type', v_parent_type,
        'parent_video_id', v_parent_id
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_student_submit_challenge(p_participation_id uuid, p_submission_text text, p_submission_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_challenge_id UUID;
    v_requires_submission BOOLEAN;
    v_new_status TEXT;
    v_is_banned BOOLEAN;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM app.challenge_user_bans b
        WHERE b.user_id = v_user_id
          AND (b.banned_until IS NULL OR b.banned_until > NOW())
    ) INTO v_is_banned;

    IF v_is_banned THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'banned_from_challenges');
    END IF;

    SELECT
        cp.challenge_id,
        c.requires_submission
    INTO v_challenge_id, v_requires_submission
    FROM app.challenge_participations cp
    JOIN app.challenges c ON c.id = cp.challenge_id
    WHERE cp.id = p_participation_id
      AND cp.user_id = v_user_id
      AND cp.is_active = TRUE;

    IF v_challenge_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'participation_not_found');
    END IF;

    IF (p_submission_text IS NULL OR LENGTH(TRIM(p_submission_text)) = 0)
       AND (p_submission_url IS NULL OR LENGTH(TRIM(p_submission_url)) = 0) THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'empty_submission');
    END IF;

    -- Plus de validation admin : la soumission complète directement le challenge
    v_new_status := 'completed';

    UPDATE app.challenge_participations cp
    SET
        submission_text = TRIM(COALESCE(p_submission_text, '')),
        submission_url = NULLIF(TRIM(COALESCE(p_submission_url, '')), ''),
        video_url = NULLIF(TRIM(COALESCE(p_submission_url, '')), ''),
        moderation_status = 'published',
        moderation_flags = NULL,
        moderated_by_admin_id = NULL,
        moderated_at = NULL,
        status = v_new_status,
        submitted_at = NOW(),
        completed_at = CASE
            WHEN v_new_status = 'completed' THEN COALESCE(cp.completed_at, NOW())
            ELSE cp.completed_at
        END,
        score = CASE
            WHEN v_new_status = 'completed' THEN COALESCE(cp.score, (
                SELECT c2.points FROM app.challenges c2 WHERE c2.id = v_challenge_id
            ), 0)
            ELSE cp.score
        END
    WHERE cp.id = p_participation_id
      AND cp.user_id = v_user_id
      AND cp.is_active = TRUE;

    IF NOT FOUND THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'update_failed');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'participation_id', p_participation_id);
END;
$function$

