CREATE OR REPLACE FUNCTION public.app_university_update_application_status(p_application_id uuid, p_new_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_university_id UUID;
    v_exists BOOLEAN;
    v_app_id UUID;
    v_status TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT
        raw_user_meta_data->>'role',
        (raw_user_meta_data->>'university_id')::UUID
    INTO v_role, v_university_id
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'university' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_university');
    END IF;

    IF v_university_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'university_not_configured');
    END IF;

    IF p_new_status IS NULL OR LENGTH(TRIM(p_new_status)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_status');
    END IF;

    IF p_new_status NOT IN ('under_review', 'accepted', 'rejected', 'canceled') THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'unsupported_status');
    END IF;

    SELECT EXISTS(
        SELECT 1
        FROM app.applications a
        JOIN app.programs p ON p.id = a.program_id
        WHERE a.id = p_application_id
          AND p.university_id = v_university_id
    ) INTO v_exists;

    IF NOT v_exists THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'application_not_found');
    END IF;

    UPDATE app.applications a
    SET status = p_new_status,
        updated_at = NOW()
    WHERE a.id = p_application_id
    RETURNING a.id, a.status INTO v_app_id, v_status;

    IF v_app_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'application_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT(
        'success', TRUE,
        'application_id', v_app_id,
        'status', v_status
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_upsert_university_course(p_course_id uuid, p_program_id uuid, p_title text, p_description text, p_credits integer, p_prerequisites text, p_instructor text, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_university_id UUID;
    v_course_id UUID;
    v_program_id UUID;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT
        raw_user_meta_data->>'role',
        (raw_user_meta_data->>'university_id')::UUID
    INTO v_role, v_university_id
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'university' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_university');
    END IF;

    IF v_university_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'university_not_configured');
    END IF;

    IF p_title IS NULL OR LENGTH(TRIM(p_title)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_title');
    END IF;

    IF p_course_id IS NULL AND p_program_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'program_required');
    END IF;

    IF p_program_id IS NOT NULL THEN
        SELECT id
        INTO v_program_id
        FROM app.programs
        WHERE id = p_program_id
          AND university_id = v_university_id;

        IF v_program_id IS NULL THEN
            RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'program_not_found');
        END IF;
    END IF;

    IF p_course_id IS NULL THEN
        INSERT INTO app.courses (
            program_id,
            title,
            description,
            credits,
            prerequisites,
            instructor,
            is_active
        )
        VALUES (
            COALESCE(v_program_id, p_program_id),
            p_title,
            p_description,
            p_credits,
            p_prerequisites,
            p_instructor,
            COALESCE(p_is_active, TRUE)
        )
        RETURNING id INTO v_course_id;
    ELSE
        UPDATE app.courses c
        SET
            program_id = COALESCE(v_program_id, c.program_id),
            title = p_title,
            description = p_description,
            credits = p_credits,
            prerequisites = p_prerequisites,
            instructor = p_instructor,
            is_active = COALESCE(p_is_active, is_active),
            updated_at = NOW()
        FROM app.programs p
        WHERE c.id = p_course_id
          AND c.program_id = p.id
          AND p.university_id = v_university_id
        RETURNING c.id INTO v_course_id;
    END IF;

    IF v_course_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'course_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'course_id', v_course_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.app_upsert_university_media(p_media_id uuid, p_media_type text, p_title text, p_description text, p_url text, p_storage_path text, p_thumbnail_url text, p_sort_order integer, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_user_id UUID := auth.uid();
    v_role TEXT;
    v_university_id UUID;
    v_media_id UUID;
    v_type TEXT;
    v_is_file BOOLEAN;
    v_url_trim TEXT;
    v_storage_path_trim TEXT;
BEGIN
    IF v_user_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
    END IF;

    SELECT
        raw_user_meta_data->>'role',
        (raw_user_meta_data->>'university_id')::UUID
    INTO v_role, v_university_id
    FROM auth.users
    WHERE id = v_user_id;

    IF v_role <> 'university' THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_university');
    END IF;

    IF v_university_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'university_not_configured');
    END IF;

    IF p_media_type IS NULL OR LENGTH(TRIM(p_media_type)) = 0 THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'invalid_media_type');
    END IF;

    v_type := LOWER(TRIM(COALESCE(p_media_type, '')));
    v_is_file := POSITION('video' IN v_type) > 0
                 OR POSITION('image' IN v_type) > 0
                 OR POSITION('brochure' IN v_type) > 0
                 OR POSITION('pdf' IN v_type) > 0
                 OR POSITION('doc' IN v_type) > 0;

    v_url_trim := TRIM(COALESCE(p_url, ''));
    v_storage_path_trim := TRIM(COALESCE(p_storage_path, ''));

    IF v_is_file THEN
        IF v_storage_path_trim = '' THEN
            RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'storage_required');
        END IF;

        IF v_url_trim ILIKE '%stream.mux.com%' THEN
            RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'mux_not_allowed');
        END IF;

        IF v_url_trim LIKE 'http%' AND
           v_url_trim NOT LIKE 'https://thevdfcwlcqzdoybfvgs.supabase.co%' THEN
            RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'media_url_not_allowed');
        END IF;
    END IF;

    IF p_media_id IS NULL THEN
        INSERT INTO app.university_media (
            university_id,
            media_type,
            title,
            description,
            url,
            storage_path,
            thumbnail_url,
            sort_order,
            is_active
        )
        VALUES (
            v_university_id,
            p_media_type,
            p_title,
            p_description,
            v_url_trim,
            v_storage_path_trim,
            p_thumbnail_url,
            COALESCE(p_sort_order, 0),
            COALESCE(p_is_active, TRUE)
        )
        RETURNING id INTO v_media_id;
    ELSE
        UPDATE app.university_media
        SET
            media_type = p_media_type,
            title = p_title,
            description = p_description,
            url = p_url,
            storage_path = p_storage_path,
            thumbnail_url = p_thumbnail_url,
            sort_order = COALESCE(p_sort_order, sort_order),
            is_active = COALESCE(p_is_active, is_active),
            updated_at = NOW()
        WHERE id = p_media_id
          AND university_id = v_university_id
        RETURNING id INTO v_media_id;
    END IF;

    IF v_media_id IS NULL THEN
        RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'media_not_found');
    END IF;

    RETURN JSONB_BUILD_OBJECT('success', TRUE, 'media_id', v_media_id);
END;
$function$

